// Command iconify-gen converts the @iconify-json/* icon sets installed
// by pnpm into Go source under internal/components/icons: one file per
// set, exposing its icons as fields of a namespace variable referenced
// as icons.cSete.cIcone. Run it through `just icons` after changing the
// icon dependencies; commit the generated files.
package main

import (
	"encoding/json"
	"fmt"
	"go/format"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

const iconsDir = "internal/components/icons"

// setDoc mirrors the Iconify icons.json format. Entries using rotate or
// flip transforms and alias entries are rejected until a consumer
// actually needs them; hidden entries are skipped as the format marks
// them kept only for backward compatibility.
type setDoc struct {
	Prefix string `json:"prefix"`
	Width  int    `json:"width"`
	Height int    `json:"height"`
	Icons  map[string]struct {
		Body   string `json:"body"`
		Left   int    `json:"left"`
		Top    int    `json:"top"`
		Width  int    `json:"width"`
		Height int    `json:"height"`
		Rotate int    `json:"rotate"`
		HFlip  bool   `json:"hFlip"`
		VFlip  bool   `json:"vFlip"`
		Hidden bool   `json:"hidden"`
	} `json:"icons"`
	Aliases map[string]json.RawMessage `json:"aliases"`
}

func main() {
	sets, err := iconifySets("package.json")
	if err != nil {
		fatal(err)
	}
	if len(sets) == 0 {
		fatal(fmt.Errorf("package.json declares no @iconify-json/* dependency"))
	}
	for _, set := range sets {
		data, err := os.ReadFile(
			filepath.Join("node_modules", "@iconify-json", set, "icons.json"),
		)
		if err != nil {
			fatal(
				fmt.Errorf(
					"read set %s (run pnpm install first): %w",
					set,
					err,
				),
			)
		}
		version, license := packageInfo(set)
		source, err := generate(set, version, license, data)
		if err != nil {
			fatal(err)
		}
		target := filepath.Join(iconsDir, set+"_gen.go")
		if err := os.MkdirAll(iconsDir, 0o755); err != nil {
			fatal(err)
		}
		if err := os.WriteFile(target, source, 0o600); err != nil {
			fatal(err)
		}
		fmt.Printf("%s -> %s\n", set, target)
	}
}

func fatal(err error) {
	fmt.Fprintln(os.Stderr, "iconify-gen:", err)
	os.Exit(1)
}

// iconifySets returns the set names declared as @iconify-json/*
// dependencies in the given package.json.
func iconifySets(path string) ([]string, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	var manifest struct {
		Dependencies    map[string]string `json:"dependencies"`
		DevDependencies map[string]string `json:"devDependencies"`
	}
	if err := json.Unmarshal(data, &manifest); err != nil {
		return nil, fmt.Errorf("parse %s: %w", path, err)
	}
	seen := map[string]bool{}
	var sets []string
	for _, deps := range []map[string]string{manifest.Dependencies, manifest.DevDependencies} {
		for name := range deps {
			set, ok := strings.CutPrefix(name, "@iconify-json/")
			if ok && !seen[set] {
				seen[set] = true
				sets = append(sets, set)
			}
		}
	}
	sort.Strings(sets)
	return sets, nil
}

// packageInfo reads the installed set's version and license for the
// generated file header.
func packageInfo(set string) (version, license string) {
	data, err := os.ReadFile(
		filepath.Join("node_modules", "@iconify-json", set, "package.json"),
	)
	if err != nil {
		return "unknown", "unknown license"
	}
	var manifest struct {
		Version string `json:"version"`
		License string `json:"license"`
	}
	if err := json.Unmarshal(data, &manifest); err != nil {
		return "unknown", "unknown license"
	}
	return manifest.Version, manifest.License
}

// generate renders one Go file holding the set's visible icons as fields
// of a single namespace variable, referenced as icons.<Set>.<Icon>.
func generate(set, version, license string, data []byte) ([]byte, error) {
	var doc setDoc
	if err := json.Unmarshal(data, &doc); err != nil {
		return nil, fmt.Errorf("parse set %s: %w", set, err)
	}
	if len(doc.Aliases) != 0 {
		return nil, fmt.Errorf(
			"set %s uses aliases, which we do not resolve",
			set,
		)
	}
	if doc.Prefix == "" {
		doc.Prefix = set
	}
	if doc.Width == 0 {
		doc.Width = 24
	}
	if doc.Height == 0 {
		doc.Height = 24
	}

	var b strings.Builder
	fmt.Fprintf(
		&b,
		"// Code generated by cmd/iconify-gen from @iconify-json/%s@%s (%s); DO NOT EDIT.\n\npackage icons\n\nimport \"github.com/egoist/mygo/ui\"\n",
		set,
		version,
		license,
	)

	names := make([]string, 0, len(doc.Icons))
	for name, icon := range doc.Icons {
		if icon.Hidden {
			continue
		}
		names = append(names, name)
	}
	sort.Strings(names)
	type field struct {
		name, body               string
		left, top, width, height int
	}
	var fields []field
	for _, name := range names {
		icon := doc.Icons[name]
		if icon.Rotate != 0 || icon.HFlip || icon.VFlip {
			return nil, fmt.Errorf(
				"set %s icon %q uses rotate/flip, which we do not transform yet",
				set,
				name,
			)
		}
		if strings.ContainsRune(icon.Body, '`') {
			return nil, fmt.Errorf(
				"set %s icon %q has a backtick in its body",
				set,
				name,
			)
		}
		width, height := icon.Width, icon.Height
		if width == 0 {
			width = doc.Width
		}
		if height == 0 {
			height = doc.Height
		}
		fields = append(fields, field{
			name:   name,
			body:   icon.Body,
			left:   icon.Left,
			top:    icon.Top,
			width:  width,
			height: height,
		})
	}
	if len(fields) == 0 {
		return nil, fmt.Errorf("set %s has no visible icons", set)
	}

	setName := pascal(doc.Prefix)
	fmt.Fprintf(
		&b,
		"\n// %s holds the icons of the %s set.\nvar %s = struct {\n",
		setName,
		doc.Prefix,
		setName,
	)
	for _, f := range fields {
		fmt.Fprintf(
			&b,
			"\t// %s is the %q icon of the %s set.\n\t%s *ui.SVG\n",
			pascal(f.name),
			f.name,
			doc.Prefix,
			pascal(f.name),
		)
	}
	b.WriteString("}{\n")
	for _, f := range fields {
		fmt.Fprintf(
			&b,
			"\t%s: ui.MustParseSVG([]byte(`<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"%d %d %d %d\">%s</svg>`)),\n",
			pascal(f.name),
			f.left,
			f.top,
			f.width,
			f.height,
			f.body,
		)
	}
	b.WriteString("}\n")

	source, err := format.Source([]byte(b.String()))
	if err != nil {
		return nil, fmt.Errorf("format generated set %s: %w", set, err)
	}
	return source, nil
}

// pascal converts an Iconify kebab-case name into an exported Go
// identifier.
func pascal(name string) string {
	var b strings.Builder
	for _, part := range strings.FieldsFunc(name, func(r rune) bool {
		return r == '-' || r == '_'
	}) {
		if part == "" {
			continue
		}
		b.WriteString(strings.ToUpper(part[:1]) + part[1:])
	}
	result := b.String()
	if result == "" || result[0] >= '0' && result[0] <= '9' {
		return "Icon" + result
	}
	return result
}
